class Solution:
    def minimizeArrayValue(self, nums):
        ans=s=0
        for i,x in enumerate(nums):
            s+=x
            ans=max(ans,(s+i)//(i+1)+(1 if s%(i+1) else 0))
        return ans

c.cpp:
class Solution {
public:
    int minimizeArrayValue(vector<int>& nums){
        long long s=0; int ans=0;
        for(int i=0;i<nums.size();i++){
            s+=nums[i];
            ans=max(ans,(int)((s+i)/(i+1)));
        }
        return ans;
    }
};

c.java:
class Solution {
    public int minimizeArrayValue(int[] nums){
        long s=0; int ans=0;
        for(int i=0;i<nums.length;i++){
            s+=nums[i];
            ans=(int)Math.max(ans,(s+i)/(i+1));
        }
        return ans;
    }
}

